import React, { useState } from 'react';

import { Pressable, View } from 'react-native';

import { Feather } from '@expo/vector-icons';
import { KeyboardAwareScrollView } from 'react-native-keyboard-controller';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useRouter } from 'expo-router';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Text } from '@/components/ui/text';
import { useFormValidation } from '@/lib/hooks/use-form-validation';
import { loginSchema } from '@/lib/schemas/auth-schemas';
import { useAuthStore } from '@/lib/stores/auth-store';
import { showToast } from '@/lib/toast';

export default function LoginScreen() {
  const router = useRouter();
  const email = useAuthStore((state) => state.email);
  const setEmail = useAuthStore((state) => state.setEmail);
  const [password, setPassword] = useState('');

  const { errors, handleSubmit, clearError, hasSubmitted } = useFormValidation({
    schema: loginSchema,
    mode: 'onChange',
  });

  const onSubmit = () => {
    handleSubmit({ email, password }, async (data) => {
      try {
        // TODO: Implement actual login with Better Auth + Convex
        console.log('Valid login data:', data);
        showToast.success('Login successful!', 'Welcome back');
        router.push('/');
      } catch (error) {
        showToast.error(
          'Login failed',
          error instanceof Error ? error.message : 'Invalid credentials'
        );
      }
    });
  };

  return (
    <SafeAreaView className="flex-1 bg-black-1" edges={['top']}>
      <KeyboardAwareScrollView
        className="flex-1 px-6"
        contentContainerStyle={{ flexGrow: 1, justifyContent: 'space-between' }}
      >
        <View className="flex w-full items-start justify-center gap-1">
          <View className="mb-6 flex w-full flex-row items-center justify-center gap-2">
            <Text className="text-4xl">Welcome Back!</Text>
          </View>
          <Input
            value={email}
            onChangeText={(text) => {
              setEmail(text);
              if (hasSubmitted) clearError('email');
            }}
            placeholder="Email"
            keyboardType="email-address"
            autoCapitalize="none"
            autoComplete="email"
            autoCorrect={false}
            style={{ backgroundColor: '#202020' }}
            className="h-12"
            aria-invalid={!!errors.email}
          />
          <Input
            value={password}
            onChangeText={(text) => {
              setPassword(text);
              if (hasSubmitted) clearError('password');
            }}
            placeholder="Password"
            autoCapitalize="none"
            secureTextEntry={true}
            autoComplete="password"
            autoCorrect={false}
            style={{ backgroundColor: '#202020' }}
            className="h-12"
            aria-invalid={!!errors.password}
          />
          <Pressable
            onPress={() => {
              router.push('/forgot-password');
            }}
          >
            <Text className="mt-1 pl-2 text-blue-400">Forgot Password?</Text>
          </Pressable>
        </View>

        <View className="flex-1" />

        <View className="mb-6 flex w-full items-center justify-center">
          <Button className="w-full" onPress={onSubmit}>
            <Text>Continue with email</Text>
            <Feather name="arrow-right" size={24} color="black" />
          </Button>
          <Pressable
            onPress={() => {
              router.replace('/register');
            }}
          >
            <Text className="mt-4 pl-2 text-blue-400">
              Dont have an account?
            </Text>
          </Pressable>
        </View>
      </KeyboardAwareScrollView>
    </SafeAreaView>
  );
}
